package com.nigson.commerce.affiliate;

import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import com.nigson.commerce.platform.*;
import com.nigson.shared.security.ActorAssertion;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import tools.jackson.databind.JsonNode;

/** Manual recording only. No bank/provider transfer is initiated by this service. */
public final class AffiliatePayouts {
 public record Bank(UUID id,long version,long revision,String bankName,String accountName,String accountLast4,String accountNumber,String status,String reviewReason){}
 public record Balance(String pending,String available,String held,String reversed,String paid,String reserved,String recovery){}
 public record Payout(UUID id,long version,String period,String state,String amount,String transferReference,Instant createdAt,Instant paidAt){}
 public record Overview(UUID partyId,String name,String affiliateState,Bank bank,Balance balance,List<Payout> payouts,int page,long totalPages,boolean canPrepare,boolean canTransfer){}
 public record Page(List<Overview> items,int page,long totalPages){}
 private final JdbcTemplate jdbc;private final AffiliateLinks links;private final AffiliateCommissions commissions;private final AffiliateBankSecrets secrets;private final PlatformStore commands;private final AuditWriter audit;private final TransactionTemplate tx;private final Clock clock;
 public AffiliatePayouts(JdbcTemplate jdbc,AffiliateLinks links,AffiliateCommissions commissions,AffiliateBankSecrets secrets,PlatformStore commands,AuditWriter audit,PlatformTransactionManager manager,Clock clock){this.jdbc=jdbc;this.links=links;this.commissions=commissions;this.secrets=secrets;this.commands=commands;this.audit=audit;this.tx=new TransactionTemplate(manager);tx.setTimeout(10);this.clock=clock;}
 private Problem.Failure conflict(){return new Problem.Failure(ProblemCode.CONFLICT);}
 private void staff(ActorAssertion.Actor actor){if(actor==null)throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);if(actor.organization()!=null)throw new Problem.Failure(ProblemCode.ACCESS_DENIED);var roles=jdbc.query("SELECT r.role FROM commerce.party p JOIN commerce.staff_role_assignment r ON r.party_id=p.id WHERE p.id=? AND p.identity_issuer=? AND p.identity_subject=? AND p.status='ACTIVE' AND r.revoked_at IS NULL AND r.role IN ('ADMIN','FINANCE')",(r,n)->r.getString(1),actor.party(),actor.identityIssuer(),actor.identitySubject());if(roles.stream().noneMatch(actor.roles()::contains))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}
 private void lock(UUID party){if(jdbc.query("SELECT id FROM commerce.party WHERE id=? FOR UPDATE",(r,n)->r.getObject(1,UUID.class),party).isEmpty())throw new Problem.Failure(ProblemCode.NOT_FOUND);}
 private String affiliate(UUID party){var states=jdbc.query("SELECT e.status FROM commerce.account_entitlement e JOIN commerce.organization o ON o.id=e.organization_id JOIN commerce.organization_membership m ON m.organization_id=o.id JOIN commerce.party p ON p.id=m.party_id WHERE m.party_id=? AND p.status='ACTIVE' AND m.status='ACTIVE' AND o.status='ACTIVE' AND e.entitlement='AFFILIATE_MARKETING' AND e.partner_type='AFFILIATE'",(r,n)->r.getString(1),party);if(states.size()!=1||!Set.of("ACTIVE","SUSPENDED").contains(states.getFirst()))throw new Problem.Failure(ProblemCode.NOT_FOUND);return states.getFirst();}
 private Map<String,Object> latest(UUID party){var rows=jdbc.queryForList("SELECT * FROM commerce.affiliate_bank_detail WHERE party_id=? ORDER BY revision DESC LIMIT 1",party);return rows.isEmpty()?null:rows.getFirst();}
 private AffiliateBankSecrets.Details open(Map<String,Object> row){return secrets.open((UUID)row.get("id"),(UUID)row.get("party_id"),(byte[])row.get("payload_ciphertext"),(String)row.get("content_hash"),(String)row.get("cipher_mode"));}
 private Bank bank(Map<String,Object> row,boolean reveal){if(row==null)return null;var secret=open(row);String number=secret.accountNumber();return new Bank((UUID)row.get("id"),((Number)row.get("version")).longValue(),((Number)row.get("revision")).longValue(),secret.bankName(),secret.accountName(),number.substring(6),reveal?number:null,(String)row.get("status"),(String)row.get("review_reason"));}
 private boolean prepared(UUID party){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.affiliate_payout WHERE party_id=? AND state='PREPARED')",Boolean.class,party));}
 private boolean paidThisMonth(UUID party){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.affiliate_payout WHERE party_id=? AND period=? AND state='PAID')",Boolean.class,party,period()));}
 private void referenceAvailable(String reference){jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(r,n)->1,"affiliate-transfer:"+reference);if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.affiliate_payout WHERE transfer_reference=?)",Boolean.class,reference)))throw conflict();}
 private String period(){return YearMonth.from(clock.instant().atZone(ZoneId.of("Africa/Lagos"))).toString();}
 private String money(BigDecimal amount){return amount.setScale(2).toPlainString();}
 private Balance balance(UUID party){var earned=commissions.earnings(party,0);var paid=jdbc.queryForMap("SELECT coalesce(sum(amount) FILTER(WHERE state='PAID'),0) AS paid,coalesce(sum(amount) FILTER(WHERE state='PREPARED'),0) AS reserved FROM commerce.affiliate_payout WHERE party_id=?",party);BigDecimal available=new BigDecimal(earned.available()),sent=(BigDecimal)paid.get("paid"),reserved=(BigDecimal)paid.get("reserved");return new Balance(earned.pending(),money(available.subtract(sent).subtract(reserved).max(BigDecimal.ZERO)),earned.held(),earned.reversed(),money(sent),money(reserved),money(sent.subtract(available).max(BigDecimal.ZERO)));}
 private Payout payout(Map<String,Object> row){return new Payout((UUID)row.get("id"),((Number)row.get("version")).longValue(),(String)row.get("period"),(String)row.get("state"),money((BigDecimal)row.get("amount")),(String)row.get("transfer_reference"),((java.sql.Timestamp)row.get("created_at")).toInstant(),row.get("paid_at")==null?null:((java.sql.Timestamp)row.get("paid_at")).toInstant());}
 private Overview overview(UUID party,int page,boolean reveal){if(page<0||page>10000)throw ApiValues.invalid();String state=affiliate(party);Bank bank=bank(latest(party),reveal);Balance balance=balance(party);var history=jdbc.queryForList("SELECT * FROM commerce.affiliate_payout WHERE party_id=? ORDER BY created_at DESC,id DESC LIMIT 20 OFFSET ?",party,page*20).stream().map(this::payout).toList();long count=jdbc.queryForObject("SELECT count(*) FROM commerce.affiliate_payout WHERE party_id=?",Long.class,party);boolean monthly=Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.affiliate_payout WHERE party_id=? AND period=? AND state IN ('PREPARED','PAID'))",Boolean.class,party,period()));boolean reviewed=bank!=null&&bank.status().equals("APPROVED");BigDecimal qualified=new BigDecimal(commissions.earnings(party,0).available());boolean canTransfer=state.equals("ACTIVE")&&reviewed&&new BigDecimal(balance.reserved()).signum()>0&&qualified.compareTo(new BigDecimal(balance.paid()).add(new BigDecimal(balance.reserved())))>=0;return new Overview(party,jdbc.queryForObject("SELECT display_name FROM commerce.party WHERE id=?",String.class,party),state,bank,balance,history,page,(count+19)/20,state.equals("ACTIVE")&&reviewed&&!monthly&&!prepared(party)&&new BigDecimal(balance.available()).signum()>0,canTransfer);}
 public Overview own(ActorAssertion.Actor actor,int page){if(!Set.of("ACTIVE","SUSPENDED").contains(links.status(actor).state()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return tx.execute(s->overview(actor.party(),page,false));}
 public Page list(ActorAssertion.Actor actor,int page){staff(actor);if(page<0||page>10000)throw ApiValues.invalid();return tx.execute(s->{staff(actor);String query=" FROM commerce.party p WHERE p.status='ACTIVE' AND EXISTS(SELECT 1 FROM commerce.organization_membership m JOIN commerce.organization o ON o.id=m.organization_id JOIN commerce.account_entitlement e ON e.organization_id=o.id WHERE m.party_id=p.id AND m.status='ACTIVE' AND o.status='ACTIVE' AND e.entitlement='AFFILIATE_MARKETING' AND e.partner_type='AFFILIATE' AND e.status IN ('ACTIVE','SUSPENDED'))";long count=jdbc.queryForObject("SELECT count(*)"+query,Long.class);var items=jdbc.query("SELECT p.id"+query+" ORDER BY p.created_at DESC,p.id LIMIT 20 OFFSET ?",(r,n)->r.getObject(1,UUID.class),page*20).stream().map(id->overview(id,0,false)).toList();return new Page(items,page,(count+19)/20);});}
 public Overview detail(ActorAssertion.Actor actor,UUID party,int page,UUID correlation){staff(actor);return tx.execute(s->{staff(actor);var result=overview(party,page,true);if(result.bank()!=null)audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.AFFILIATE_BANK_READ,AuditValues.Resource.AFFILIATE_BANK,result.bank().id(),correlation,AuditValues.Reason.OPERATOR_REQUEST,null,null,null);return result;});}
 private static void exact(JsonNode body,Set<String> keys){if(body==null||!body.isObject()||!body.propertyNames().equals(keys))throw ApiValues.invalid();}
 private static String text(JsonNode body,String name,int min,int max){var value=body.get(name);if(value==null||!value.isString())throw ApiValues.invalid();String result=value.asString().trim();if(result.length()<min||result.length()>max||result.codePoints().anyMatch(Character::isISOControl))throw ApiValues.invalid();return result;}
 private static UUID id(JsonNode body,String name){return ApiValues.uuid(text(body,name,36,36));}
 private static long version(JsonNode body){var value=body.get("version");if(value==null||!value.isIntegralNumber()||!value.canConvertToLong()||value.asLong()<0)throw ApiValues.invalid();return value.asLong();}
 private UUID bankCommandId(UUID party,String key){String hash=EventCodec.hash(EventCodec.JSON.valueToTree(Map.of("purpose","affiliate-bank-revision","partyId",party,"requestId",ApiValues.uuid(key))));return new UUID((Long.parseUnsignedLong(hash.substring(0,16),16)&0xffffffffffff0fffL)|0x8000L,(Long.parseUnsignedLong(hash.substring(16,32),16)&0x3fffffffffffffffL)|0x8000000000000000L);}
 public Overview saveBank(ActorAssertion.Actor actor,JsonNode body,String key,UUID correlation){try{return saveBankInternal(actor,body,key,correlation);}catch(org.springframework.dao.DuplicateKeyException duplicate){throw conflict();}}
 private Overview saveBankInternal(ActorAssertion.Actor actor,JsonNode body,String key,UUID correlation){exact(body,Set.of("expectedBankId","bankName","accountName","accountNumber"));UUID command=bankCommandId(actor.party(),key),previous=body.path("expectedBankId").isNull()?null:id(body,"expectedBankId");String bank=text(body,"bankName",2,120),name=text(body,"accountName",2,160),number=text(body,"accountNumber",10,10);if(!number.matches("[0-9]{10}"))throw ApiValues.invalid();if(!links.status(actor).state().equals("ACTIVE"))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);
  return tx.execute(s->{lock(actor.party());if(!links.status(actor).state().equals("ACTIVE"))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);var replay=jdbc.queryForList("SELECT * FROM commerce.affiliate_bank_detail WHERE id=? AND party_id=?",command,actor.party());if(!replay.isEmpty()){var row=replay.getFirst();var secret=open(row);if(!Objects.equals(row.get("previous_id"),previous)||!secret.bankName().equals(bank)||!secret.accountName().equals(name)||!secret.accountNumber().equals(number))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);return overview(actor.party(),0,false);}var current=latest(actor.party());if(!Objects.equals(current==null?null:current.get("id"),previous))throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(prepared(actor.party()))throw conflict();var sealed=secrets.seal(command,actor.party(),bank,name,number);long revision=current==null?1:((Number)current.get("revision")).longValue()+1;jdbc.update("INSERT INTO commerce.affiliate_bank_detail(id,created_by,updated_by,party_id,revision,previous_id,payload_ciphertext,content_hash,cipher_mode,status) VALUES (?,?,?,?,?,?,?,?,?,'PENDING')",command,actor.party().toString(),actor.party().toString(),actor.party(),revision,previous,sealed.ciphertext(),sealed.hash(),sealed.mode());audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.AFFILIATE_BANK_SAVE,AuditValues.Resource.AFFILIATE_BANK,command,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("revision",revision),null);return overview(actor.party(),0,false);});
 }
 private PlatformStore.Response command(ActorAssertion.Actor actor,String operation,String key,JsonNode body,java.util.function.Function<JdbcTemplate,PlatformStore.Response> action){staff(actor);ApiValues.idempotencyKey(key);try{return commands.executeLocal(actor.party().toString(),operation,key,body,action);}catch(PlatformStore.Conflict failure){throw new Problem.Failure(failure.getMessage().equals("IDEMPOTENCY_HASH_MISMATCH")?ProblemCode.IDEMPOTENCY_HASH_MISMATCH:ProblemCode.IDEMPOTENCY_IN_PROGRESS);}catch(org.springframework.dao.DuplicateKeyException duplicate){throw conflict();}}
 private PlatformStore.Response reply(UUID id){return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(Map.of("id",id)),id);}
 public void review(ActorAssertion.Actor actor,UUID party,JsonNode body,String key,UUID correlation){exact(body,Set.of("bankId","version","decision","reason"));UUID bankId=id(body,"bankId");long expected=version(body);String decision=text(body,"decision",8,8),reason=text(body,"reason",3,500);if(!Set.of("APPROVED","REJECTED").contains(decision))throw ApiValues.invalid();var request=EventCodec.JSON.createObjectNode();request.put("partyId",party.toString());request.set("input",body);command(actor,"API-230",key,request,db->{lock(party);staff(actor);affiliate(party);var bank=latest(party);if(bank==null||!bank.get("id").equals(bankId)||((Number)bank.get("version")).longValue()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!bank.get("status").equals("PENDING")||prepared(party))throw conflict();jdbc.update("UPDATE commerce.affiliate_bank_detail SET status=?,reviewed_by=?,reviewed_at=?,review_reason=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",decision,actor.party(),java.sql.Timestamp.from(clock.instant()),reason,java.sql.Timestamp.from(clock.instant()),actor.party().toString(),bankId);audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.AFFILIATE_BANK_REVIEW,AuditValues.Resource.AFFILIATE_BANK,bankId,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("version",expected+1),null);return reply(bankId);});staff(actor);}
 public Payout prepare(ActorAssertion.Actor actor,UUID party,JsonNode body,String key,UUID correlation){exact(body,Set.of("bankId"));UUID bankId=id(body,"bankId"),commandId=ApiValues.uuid(key);staff(actor);var historical=jdbc.queryForList("SELECT * FROM commerce.affiliate_payout WHERE id=?",commandId);if(!historical.isEmpty()){var saved=historical.getFirst();if(!party.equals(saved.get("party_id"))||!bankId.equals(saved.get("bank_detail_id"))||!actor.party().toString().equals(saved.get("created_by")))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);return payout(saved);}var request=EventCodec.JSON.valueToTree(Map.of("partyId",party,"bankId",bankId));var result=command(actor,"API-231",key,request,db->{lock(party);staff(actor);if(!affiliate(party).equals("ACTIVE"))throw conflict();var bank=latest(party);if(bank==null||!bank.get("id").equals(bankId)||!bank.get("status").equals("APPROVED"))throw conflict();if(prepared(party)||paidThisMonth(party))throw conflict();BigDecimal amount=new BigDecimal(balance(party).available());if(amount.signum()<=0)throw conflict();UUID payout=commandId;jdbc.update("INSERT INTO commerce.affiliate_payout(id,created_at,created_by,updated_by,party_id,bank_detail_id,period,state,amount) VALUES (?,?,?,?,?,?,?,'PREPARED',?)",payout,java.sql.Timestamp.from(clock.instant()),actor.party().toString(),actor.party().toString(),party,bankId,period(),amount);audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.AFFILIATE_PAYOUT_PREPARE,AuditValues.Resource.AFFILIATE_PAYOUT,payout,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("amount",money(amount),"currency","NGN"),null);return reply(payout);});staff(actor);return payout(jdbc.queryForMap("SELECT * FROM commerce.affiliate_payout WHERE id=?",result.resource()));}
 public Payout resolve(ActorAssertion.Actor actor,UUID payout,boolean paid,JsonNode body,String key,UUID correlation){exact(body,paid?Set.of("version","transferReference","confirmTransferred"):Set.of("version","reason","confirmNoTransfer"));long expected=version(body);String value=text(body,paid?"transferReference":"reason",paid?1:3,paid?120:500);String confirmation=paid?"confirmTransferred":"confirmNoTransfer";if(!body.path(confirmation).isBoolean()||!body.path(confirmation).asBoolean()||paid&&!value.matches("[A-Za-z0-9][A-Za-z0-9_./:-]{0,119}"))throw ApiValues.invalid();var request=EventCodec.JSON.createObjectNode();request.put("payoutId",payout.toString());request.set("input",body);var result=command(actor,paid?"API-232":"API-233",key,request,db->{var parties=jdbc.query("SELECT party_id FROM commerce.affiliate_payout WHERE id=?",(r,n)->r.getObject(1,UUID.class),payout);if(parties.isEmpty())throw new Problem.Failure(ProblemCode.NOT_FOUND);lock(parties.getFirst());staff(actor);var current=jdbc.queryForMap("SELECT * FROM commerce.affiliate_payout WHERE id=? FOR UPDATE",payout);if(((Number)current.get("version")).longValue()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!current.get("state").equals("PREPARED"))throw conflict();if(paid)referenceAvailable(value);jdbc.update("UPDATE commerce.affiliate_payout SET state=?,transfer_reference=?,paid_at=?,resolved_by=?,cancel_reason=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",paid?"PAID":"CANCELLED",paid?value:null,paid?java.sql.Timestamp.from(clock.instant()):null,actor.party(),paid?null:value,java.sql.Timestamp.from(clock.instant()),actor.party().toString(),payout);audit.append(actor.party().toString(),AuditValues.ActorKind.USER,paid?AuditValues.Action.AFFILIATE_PAYOUT_PAID:AuditValues.Action.AFFILIATE_PAYOUT_CANCEL,AuditValues.Resource.AFFILIATE_PAYOUT,payout,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("version",expected+1,"amount",money((BigDecimal)current.get("amount")),"currency","NGN"),null);return reply(payout);});staff(actor);return payout(jdbc.queryForMap("SELECT * FROM commerce.affiliate_payout WHERE id=?",result.resource()));}
}
